""" Class to handle reporting duties """
import squishtest3 as sq


class Desktop:
    """Gives access to all Squish functionality

    Attributes
    ---------

    tst_name: str
        name of test cases

    tst_report_name: str
        name of test report

    tst_aut_name: str
        name of windows application as set in squishserver

    tst_format: str
        test report format, one of (xml,html,junit,json)

    Methods
    --------

    create_squish()
        returns a squishtest object

    test_section()
        a context manager to call end test section pairwise

    """

    def __init__(self,tst_name: str, tst_report_name: str, tst_format: str, tst_aut_name: str) -> None:
        self.tname=tst_name
        self.trname=tst_report_name
        self.aut =tst_aut_name
        self.tf = tst_format

    def create_squish(self):
        """
        Creates squishtest object with options

        Returns:
            squishtest object :squishtest objects with reporting options set
        """
        sq.testSettings.testCaseName = self.tname
        sq.setTestResult(self.tf, self.trname)
        sq.testSettings.setWrappersForApplication(self.aut, ('Windows'))
        sq.testSettings.logScreenshotOnFail = True
        return sq

    @staticmethod
    def test_section(text):
        """_summary_

        Args:
            text (str): test section name

        Returns:
            class: context manager class
        """
        class Testsection:
            def __enter__(self):
                sq.test.startSection(text) #type:ignore

            def __exit__(self, exc_type, exc_value, traceback):
                sq.test.endSection() #type:ignore
        return Testsection()
